package com.turing.app.api.interview.entity;
import com.turing.app.api.user.entity.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="interview_feedback")public class InterviewFeedback{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="interview_id")private Interview interview;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="interviewer_id")private User interviewer;@Column(precision=5,scale=2)private BigDecimal score;@Column(nullable=false,length=4000)private String notes;@Column(length=2000)private String recommendation;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version@Column(nullable=false)private long version;protected InterviewFeedback(){}public static InterviewFeedback create(Interview interview,User actor,BigDecimal score,String notes,String recommendation,Instant now){InterviewFeedback v=new InterviewFeedback();v.id=UUID.randomUUID();v.interview=interview;v.interviewer=actor;v.createdAt=now;v.update(score,notes,recommendation,now);return v;}public void update(BigDecimal score,String notes,String recommendation,Instant now){this.score=score;this.notes=notes;this.recommendation=recommendation;updatedAt=now;}public UUID getId(){return id;}public User getInterviewer(){return interviewer;}public BigDecimal getScore(){return score;}public String getNotes(){return notes;}public String getRecommendation(){return recommendation;}public long getVersion(){return version;}}
